// tiled_gemm_s8: tile-sequencing wrapper around an 8x16 PE grid.
// Decomposes arbitrary M×K×N GEMMs into ceil(M/8)×ceil(N/16) tiles,
// processing each sequentially with boundary zero-padding.
module tiled_gemm_s8 #(
    parameter PM       = 8,
    parameter PN       = 16,
    parameter A_LEN    = 65536,
    parameter B_LEN    = 65536,
    parameter C_LEN    = 16384,
    parameter BIAS_LEN = 1024,
    parameter DIM_W    = 16
)(
    input                clk,
    input                rst_n,
    input                start,
    input  [DIM_W-1:0]   M_in,
    input  [DIM_W-1:0]   K_in,
    input  [DIM_W-1:0]   N_in,
    input                use_bias,
    output reg           done
);

    reg signed [7:0]  a_buf    [0:A_LEN-1];
    reg signed [7:0]  b_buf    [0:B_LEN-1];
    reg signed [31:0] bias_buf [0:BIAS_LEN-1];
    reg signed [31:0] c_buf    [0:C_LEN-1];

    // FSM states
    localparam S_IDLE    = 3'd0;
    localparam S_COMPUTE = 3'd1;
    localparam S_DRAIN   = 3'd2;
    localparam S_NEXT    = 3'd3;
    localparam S_DONE    = 3'd4;

    reg [2:0] state;

    // Dimension registers
    reg [DIM_W-1:0] M_reg, K_reg, N_reg;
    reg             use_bias_reg;

    // Tiling registers
    reg [DIM_W-1:0] mt, nt;
    reg [DIM_W-1:0] mt_count, nt_count;
    reg [DIM_W-1:0] m_base, n_base;
    reg [DIM_W-1:0] M_tile, N_tile;

    // Compute/drain control
    reg [DIM_W-1:0] cycle_cnt;
    reg [DIM_W-1:0] drain_m, drain_n;
    reg pe_en, pe_acc_clear;

    wire [DIM_W-1:0] total_cycles = K_reg + PM[DIM_W-1:0] + PN[DIM_W-1:0] - 16'd2;

    // --- PE grid (copied from systolic_mesh_s8.v) ---
    wire signed [31:0] pe_acc [0:PM*PN-1];
    wire signed [7:0] a_wire [0:PM-1][0:PN];
    wire signed [7:0] b_wire [0:PM][0:PN-1];

    genvar gi, gj;
    generate
        for (gi = 0; gi < PM; gi = gi + 1) begin : row
            for (gj = 0; gj < PN; gj = gj + 1) begin : col
                pe_s8 pe_inst (
                    .clk      (clk),
                    .rst_n    (rst_n),
                    .en       (pe_en),
                    .acc_clear(pe_acc_clear),
                    .a_in     (a_wire[gi][gj]),
                    .b_in     (b_wire[gi][gj]),
                    .a_out    (a_wire[gi][gj+1]),
                    .b_out    (b_wire[gi+1][gj]),
                    .acc      (pe_acc[gi*PN+gj])
                );
            end
        end
    endgenerate

    // --- Left-edge feeding with tile offsets and boundary check ---
    generate
        for (gi = 0; gi < PM; gi = gi + 1) begin : a_feed
            wire [DIM_W-1:0] a_offset = cycle_cnt - gi[DIM_W-1:0];
            wire [31:0]      a_addr   = (m_base + gi[DIM_W-1:0]) * K_reg + a_offset;
            wire             a_valid  = (state == S_COMPUTE) &&
                                        (cycle_cnt >= gi[DIM_W-1:0]) &&
                                        (a_offset < K_reg) &&
                                        (gi[DIM_W-1:0] < M_tile);
            assign a_wire[gi][0] = a_valid ? a_buf[a_addr[15:0]] : 8'sd0;
        end
    endgenerate

    // --- Top-edge feeding with tile offsets and boundary check ---
    generate
        for (gj = 0; gj < PN; gj = gj + 1) begin : b_feed
            wire [DIM_W-1:0] b_offset = cycle_cnt - gj[DIM_W-1:0];
            wire [31:0]      b_addr   = b_offset * N_reg + (n_base + gj[DIM_W-1:0]);
            wire             b_valid  = (state == S_COMPUTE) &&
                                        (cycle_cnt >= gj[DIM_W-1:0]) &&
                                        (b_offset < K_reg) &&
                                        (gj[DIM_W-1:0] < N_tile);
            assign b_wire[0][gj] = b_valid ? b_buf[b_addr[15:0]] : 8'sd0;
        end
    endgenerate

    // --- FSM ---
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state        <= S_IDLE;
            done         <= 1'b0;
            pe_en        <= 1'b0;
            pe_acc_clear <= 1'b0;
            cycle_cnt    <= {DIM_W{1'b0}};
            M_reg        <= {DIM_W{1'b0}};
            K_reg        <= {DIM_W{1'b0}};
            N_reg        <= {DIM_W{1'b0}};
            use_bias_reg <= 1'b0;
            mt           <= {DIM_W{1'b0}};
            nt           <= {DIM_W{1'b0}};
            mt_count     <= {DIM_W{1'b0}};
            nt_count     <= {DIM_W{1'b0}};
            m_base       <= {DIM_W{1'b0}};
            n_base       <= {DIM_W{1'b0}};
            M_tile       <= {DIM_W{1'b0}};
            N_tile       <= {DIM_W{1'b0}};
            drain_m      <= {DIM_W{1'b0}};
            drain_n      <= {DIM_W{1'b0}};
        end else begin
            case (state)
                S_IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        M_reg        <= M_in;
                        K_reg        <= K_in;
                        N_reg        <= N_in;
                        use_bias_reg <= use_bias;
                        mt_count     <= (M_in + 16'd7) >> 3;
                        nt_count     <= (N_in + 16'd15) >> 4;
                        mt           <= {DIM_W{1'b0}};
                        nt           <= {DIM_W{1'b0}};
                        m_base       <= {DIM_W{1'b0}};
                        n_base       <= {DIM_W{1'b0}};
                        M_tile       <= (M_in >= PM[DIM_W-1:0]) ? PM[DIM_W-1:0] : M_in;
                        N_tile       <= (N_in >= PN[DIM_W-1:0]) ? PN[DIM_W-1:0] : N_in;
                        cycle_cnt    <= {DIM_W{1'b0}};
                        pe_en        <= 1'b1;
                        pe_acc_clear <= 1'b1;
                        state        <= S_COMPUTE;
                    end
                end

                S_COMPUTE: begin
                    if (cycle_cnt == {DIM_W{1'b0}})
                        pe_acc_clear <= 1'b0;

                    if (cycle_cnt == total_cycles) begin
                        pe_en   <= 1'b0;
                        drain_m <= {DIM_W{1'b0}};
                        drain_n <= {DIM_W{1'b0}};
                        state   <= S_DRAIN;
                    end else begin
                        cycle_cnt <= cycle_cnt + 1'b1;
                    end
                end

                S_DRAIN: begin
                    c_buf[(m_base + drain_m) * N_reg + (n_base + drain_n)] <=
                        pe_acc[drain_m[3:0]*PN + drain_n[4:0]] +
                        (use_bias_reg ? bias_buf[m_base + drain_m] : 32'sd0);

                    if (drain_n == N_tile - 1'b1) begin
                        drain_n <= {DIM_W{1'b0}};
                        if (drain_m == M_tile - 1'b1)
                            state <= S_NEXT;
                        else
                            drain_m <= drain_m + 1'b1;
                    end else begin
                        drain_n <= drain_n + 1'b1;
                    end
                end

                S_NEXT: begin
                    if (nt + 1'b1 < nt_count) begin
                        nt           <= nt + 1'b1;
                        n_base       <= n_base + PN[DIM_W-1:0];
                        N_tile       <= ((N_reg - n_base - PN[DIM_W-1:0]) >= PN[DIM_W-1:0])
                                        ? PN[DIM_W-1:0]
                                        : (N_reg - n_base - PN[DIM_W-1:0]);
                        cycle_cnt    <= {DIM_W{1'b0}};
                        pe_en        <= 1'b1;
                        pe_acc_clear <= 1'b1;
                        state        <= S_COMPUTE;
                    end else if (mt + 1'b1 < mt_count) begin
                        mt           <= mt + 1'b1;
                        nt           <= {DIM_W{1'b0}};
                        m_base       <= m_base + PM[DIM_W-1:0];
                        n_base       <= {DIM_W{1'b0}};
                        M_tile       <= ((M_reg - m_base - PM[DIM_W-1:0]) >= PM[DIM_W-1:0])
                                        ? PM[DIM_W-1:0]
                                        : (M_reg - m_base - PM[DIM_W-1:0]);
                        N_tile       <= (N_reg >= PN[DIM_W-1:0]) ? PN[DIM_W-1:0] : N_reg;
                        cycle_cnt    <= {DIM_W{1'b0}};
                        pe_en        <= 1'b1;
                        pe_acc_clear <= 1'b1;
                        state        <= S_COMPUTE;
                    end else begin
                        state <= S_DONE;
                    end
                end

                S_DONE: begin
                    done  <= 1'b1;
                    state <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

`timescale 1ns/10ps

module tb_tiled_gemm_s8;

localparam CYCLE = 20;
localparam DIM_W = 16;

reg                 clk, rst_n, start;
reg  [DIM_W-1:0]    M_in, K_in, N_in;
reg                 use_bias;
wire                done;

tiled_gemm_s8 #(.DIM_W(DIM_W)) DUT (
    .clk(clk), .rst_n(rst_n), .start(start),
    .M_in(M_in), .K_in(K_in), .N_in(N_in),
    .use_bias(use_bias), .done(done));

initial clk = 0; always #(CYCLE/2.0) clk = ~clk;

integer M_arg, K_arg, N_arg, bias_arg, fout, k;
reg [255:0] a_path, b_path, bias_path, out_path;
reg [31:0]  cycles;
integer mn;

initial begin
    if (!$value$plusargs("M=%d", M_arg))      M_arg = 4;
    if (!$value$plusargs("K=%d", K_arg))      K_arg = 4;
    if (!$value$plusargs("N=%d", N_arg))      N_arg = 4;
    if (!$value$plusargs("bias=%d", bias_arg)) bias_arg = 0;
    if (!$value$plusargs("a=%s",   a_path))    a_path = "vectors/a.hex";
    if (!$value$plusargs("b=%s",   b_path))    b_path = "vectors/b.hex";
    if (!$value$plusargs("bi=%s",  bias_path)) bias_path = "vectors/bi.hex";
    if (!$value$plusargs("out=%s", out_path))  out_path = "vectors/out.hex";

    M_in = M_arg[DIM_W-1:0];
    K_in = K_arg[DIM_W-1:0];
    N_in = N_arg[DIM_W-1:0];
    use_bias = bias_arg[0];

    rst_n = 1; start = 0;
    $readmemh(a_path, DUT.a_buf);
    $readmemh(b_path, DUT.b_buf);
    if (bias_arg) $readmemh(bias_path, DUT.bias_buf);

    #(2*CYCLE); rst_n = 0; #(2*CYCLE); rst_n = 1;
    @(negedge clk); start = 1; @(negedge clk); start = 0;

    cycles = 0;
    while (!done) begin
        cycles = cycles + 1;
        if (cycles > 200_000_000) begin
            $display("TIMEOUT after %0d cycles", cycles); $finish;
        end
        @(negedge clk);
    end

    mn = M_arg * N_arg;
    fout = $fopen(out_path, "w");
    for (k = 0; k < mn; k = k + 1)
        $fwrite(fout, "%08x\n", DUT.c_buf[k] & 32'hffffffff);
    $fclose(fout);
    $display("tiled_gemm_s8 OK M=%0d K=%0d N=%0d bias=%0d cycles=%0d",
             M_arg, K_arg, N_arg, bias_arg, cycles);
    $finish;
end

endmodule
